import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CompletableFuture;

import javax.servlet.ServletException;

import org.eclipse.kura.deployment.agent.DeploymentAgentService;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.osgi.framework.BundleContext;
import org.osgi.framework.ServiceEvent;
import org.osgi.framework.ServiceReference;
import org.osgi.framework.ServiceRegistration;
import org.osgi.service.event.Event;
import org.slf4j.Logger;

public class PackageInstallLoggingTest {

    private static final String CREDENTIAL_URL = "https://username:secret@repository.example.com/package.dp";

    private Logger originalLogger;
    private final List<String> loggedMessages = new ArrayList<>();
    private BundleContext bundleContext;
    private DeploymentAgentService deploymentAgentService;
    private PackageInstallationTracker tracker;
    private Throwable thrownException;

    @Before
    public void setUp() throws ReflectiveOperationException {
        Field loggerField = FileServlet.class.getDeclaredField("logger");
        loggerField.setAccessible(true);
        this.originalLogger = (Logger) loggerField.get(null);
        loggerField.set(null, recordingLogger(this.loggedMessages));
        this.bundleContext = fakeBundleContext();
    }

    @After
    public void tearDown() throws ReflectiveOperationException {
        if (this.originalLogger != null) {
            Field loggerField = FileServlet.class.getDeclaredField("logger");
            loggerField.setAccessible(true);
            loggerField.set(null, this.originalLogger);
        }
    }

    @Test
    public void failedPackageInstallDoesNotLogUrlCredentials() {
        givenFailingDeploymentAgentService();

        whenInstallingPackage(CREDENTIAL_URL);

        thenServletExceptionWasThrown();
        thenLoggedMessagesContain("Failed to install package");
        thenLoggedMessagesDoNotContain("secret");
        thenLoggedMessagesDoNotContain("username");
    }

    @Test
    public void trackerCompletesWhenDeploymentAgentServiceUnregisters() {
        givenTrackerFor(CREDENTIAL_URL);

        whenDeploymentAgentServiceUnregisters();

        thenTrackerIsCompleted();
    }

    @Test
    public void trackerCompletesWhenMatchingInstalledEventArrives() {
        givenTrackerFor(CREDENTIAL_URL);

        whenInstalledEventArrivesFor(CREDENTIAL_URL);

        thenTrackerIsCompleted();
    }

    private void givenFailingDeploymentAgentService() {
        this.deploymentAgentService = (DeploymentAgentService) Proxy.newProxyInstance(
                DeploymentAgentService.class.getClassLoader(),
                new Class<?>[] { DeploymentAgentService.class }, (proxy, method, args) -> {
                    if ("installDeploymentPackageAsync".equals(method.getName())) {
                        throw new Exception("Element already exists");
                    }
                    return null;
                });
    }

    private void givenTrackerFor(String url) {
        this.tracker = new PackageInstallationTracker(url, this.bundleContext);
    }

    private void whenInstallingPackage(String url) {
        try {
            FileServlet servlet = new FileServlet(this.bundleContext);
            Method installPackage = FileServlet.class.getDeclaredMethod("installPackage",
                    DeploymentAgentService.class, String.class);
            installPackage.setAccessible(true);
            installPackage.invoke(servlet, this.deploymentAgentService, url);
        } catch (InvocationTargetException e) {
            this.thrownException = e.getTargetException();
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(e);
        }
    }

    private void whenDeploymentAgentServiceUnregisters() {
        ServiceReference<?> ref = (ServiceReference<?>) Proxy.newProxyInstance(
                ServiceReference.class.getClassLoader(), new Class<?>[] { ServiceReference.class },
                (proxy, method, args) -> null);
        this.tracker.serviceChanged(new ServiceEvent(ServiceEvent.UNREGISTERING, ref));
    }

    private void whenInstalledEventArrivesFor(String url) {
        Event event = new Event(DeploymentAgentService.EVENT_INSTALLED_TOPIC,
                Collections.singletonMap(DeploymentAgentService.EVENT_PACKAGE_URL, url));
        this.tracker.handleEvent(event);
    }

    private void thenServletExceptionWasThrown() {
        assertNotNull(this.thrownException);
        assertTrue(this.thrownException instanceof ServletException);
    }

    private void thenLoggedMessagesContain(String expected) {
        assertTrue(this.loggedMessages.stream().anyMatch(m -> m.contains(expected)));
    }

    private void thenLoggedMessagesDoNotContain(String secret) {
        assertFalse(this.loggedMessages.stream().anyMatch(m -> m.contains(secret)));
    }

    private void thenTrackerIsCompleted() {
        CompletableFuture<Void> future = this.tracker.getCompletionFuture();
        assertTrue(future.isDone());
    }

    private static BundleContext fakeBundleContext() {
        ServiceRegistration<?> registration = (ServiceRegistration<?>) Proxy.newProxyInstance(
                ServiceRegistration.class.getClassLoader(), new Class<?>[] { ServiceRegistration.class },
                (proxy, method, args) -> null);
        return (BundleContext) Proxy.newProxyInstance(BundleContext.class.getClassLoader(),
                new Class<?>[] { BundleContext.class }, (proxy, method, args) -> {
                    if ("registerService".equals(method.getName())) {
                        return registration;
                    }
                    return null;
                });
    }

    private static Logger recordingLogger(List<String> messages) {
        return (Logger) Proxy.newProxyInstance(Logger.class.getClassLoader(), new Class<?>[] { Logger.class },
                (proxy, method, args) -> {
                    if (args != null && args.length > 0) {
                        messages.add(Arrays.deepToString(args));
                    }
                    if (method.getReturnType() == boolean.class) {
                        return true;
                    }
                    return null;
                });
    }
}
